import { existsSync } from "node:fs"
import path from "node:path"

import { drizzle } from "drizzle-orm/node-postgres"
import { migrate } from "drizzle-orm/node-postgres/migrator"
import type pg from "pg"

import { classifyDatabaseError } from "@/server/db/errors"

/**
 * Versioned SQL migrations (DV-004A).
 *
 * Migrations are SQL files in `drizzle/`, generated by `yarn db:generate`,
 * reviewed and committed to Git, and applied by `yarn db:migrate`. Drizzle
 * records each applied migration in `drizzle.__drizzle_migrations` and runs
 * all pending ones inside a single transaction, so a failure leaves the
 * schema exactly as it was. Running it again when nothing is pending does
 * nothing. A PostgreSQL advisory lock stops two migrators racing.
 *
 * There is no `drizzle-kit push` here: the schema is never synchronised
 * destructively against a real database.
 */

/** Arbitrary constant: "deskvrs" as a 64-bit advisory lock key. */
const MIGRATION_LOCK_KEY = "7234298738216311"

export const MIGRATIONS_SCHEMA = "drizzle"
export const MIGRATIONS_TABLE = "__drizzle_migrations"

/** One entry of drizzle/meta/_journal.json. */
export interface JournalEntry {
  idx: number
  when: number
  tag: string
}

export interface Journal {
  entries: JournalEntry[]
}

export function migrationsFolder(projectRoot = process.cwd()) {
  return path.join(projectRoot, "drizzle")
}

export class MigrationError extends Error {
  constructor(
    message: string,
    /** The PostgreSQL error code, when there was one. */
    readonly code?: string,
  ) {
    super(message)
    this.name = "MigrationError"
  }
}

export interface MigrationStatus {
  /** Migrations in this checkout. */
  known: number
  /** Migrations recorded in the database. */
  applied: number
  /** In this checkout but not yet applied. */
  pending: string[]
  /** The newest applied migration's tag, if the checkout knows it. */
  current: string | null
  /** The database has migrations this checkout doesn't (newer code ran). */
  ahead: boolean
}

type Queryable = Pick<pg.Pool | pg.PoolClient, "query">

/** Applied migration timestamps, or [] when nothing was ever migrated. */
async function appliedTimestamps(db: Queryable): Promise<number[]> {
  const exists = await db.query<{ present: boolean }>(
    "SELECT to_regclass($1) IS NOT NULL AS present",
    [`${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE}`],
  )
  if (!exists.rows[0]?.present) return []
  const result = await db.query<{ created_at: string }>(
    `SELECT created_at FROM "${MIGRATIONS_SCHEMA}"."${MIGRATIONS_TABLE}" ORDER BY created_at`,
  )
  return result.rows.map((row) => Number(row.created_at))
}

/** Compares the database with the checkout's journal. Read-only. */
export async function migrationStatus(
  db: Queryable,
  journal: Journal,
): Promise<MigrationStatus> {
  const applied = await appliedTimestamps(db)
  const latest = applied.length > 0 ? Math.max(...applied) : -1
  const known = new Set(journal.entries.map((entry) => entry.when))
  return {
    known: journal.entries.length,
    applied: applied.length,
    pending: journal.entries
      .filter((entry) => entry.when > latest)
      .map((entry) => entry.tag),
    current:
      journal.entries.find((entry) => entry.when === latest)?.tag ?? null,
    ahead: applied.some((when) => !known.has(when)),
  }
}

/**
 * Applies pending migrations. Returns the tags it applied (empty when the
 * schema was already current).
 */
export async function runMigrations(
  pool: pg.Pool,
  journal: Journal,
  folder: string,
): Promise<string[]> {
  if (!existsSync(path.join(folder, "meta", "_journal.json")))
    throw new MigrationError(
      "The migrations folder (drizzle/) is missing its meta/_journal.json. Restore it from Git.",
    )
  let client: pg.PoolClient
  try {
    client = await pool.connect()
  } catch (error) {
    throw new MigrationError(classifyDatabaseError(error).message)
  }
  try {
    await client.query("SELECT pg_advisory_lock($1::bigint)", [
      MIGRATION_LOCK_KEY,
    ])
    try {
      const before = await migrationStatus(client, journal)
      if (before.ahead)
        throw new MigrationError(
          "This database has migrations that this checkout doesn't know about (it was migrated by newer code). Update the code before migrating.",
        )
      await migrate(drizzle({ client }), {
        migrationsFolder: folder,
        migrationsSchema: MIGRATIONS_SCHEMA,
        migrationsTable: MIGRATIONS_TABLE,
      })
      return before.pending
    } finally {
      await client
        .query("SELECT pg_advisory_unlock($1::bigint)", [MIGRATION_LOCK_KEY])
        .catch(() => {})
    }
  } catch (error) {
    if (error instanceof MigrationError) throw error
    throw migrationFailure(error)
  } finally {
    client.release()
  }
}

/**
 * Migration failures are shown to the owner in a terminal, so they keep
 * PostgreSQL's own explanation (e.g. `relation "x" already exists`), which
 * names schema objects but never credentials.
 */
function migrationFailure(error: unknown) {
  const cause = (error as { cause?: unknown }).cause ?? error
  const code = (cause as { code?: unknown }).code
  const detail = String((cause as { message?: unknown }).message ?? "")
  const classified = classifyDatabaseError(cause)
  // Connection problems get the standard fix; anything a migration's SQL
  // caused (missing table, syntax error…) gets PostgreSQL's own reason.
  const connection = [
    "offline",
    "timeout",
    "authentication",
    "missing-database",
  ]
  const explanation =
    connection.includes(classified.failure) || !detail
      ? classified.message
      : `PostgreSQL said: ${detail.split("\n")[0].slice(0, 300)}`
  return new MigrationError(
    `Migration failed and was rolled back; the schema is unchanged. ${explanation}`,
    typeof code === "string" ? code : undefined,
  )
}
